INSERT INTO purpose VALUES('surface-tui','app::App','struct','Holds the face''s state over one read-evaluate loop, so the loop''s transcript and the line being edited are read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','app::Handled','enum','Names what a key leaves the face to do, so the key''s handling is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','app::Key','enum','Names one key the face acts on, so the key''s action is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','capture::svg','function','Draws a run of the panes of a rendering as SVG on a grid of monospace cells, so the capture of a pane is the view''s own layout and a changed renderer changes it.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::Following','struct','Holds what the side view knows, so the last report of each document it heard is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::Heard','enum','Names what hearing a frame leaves the view to do, so the frame''s handling is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::Layers','enum','Names the instrument layer a terminal view asks the hub for, so a view under `--trace` hears the derivation card at the cursor.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::Seen','enum','Names what the side view has seen, so the view''s state is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::draw_following','function','Draws the side view''s frame, so the document''s cards are painted.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::drive_following','function','Drives the side view''s event loop, so the view''s frames are read and the keys are acted on.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::follow','function','Follows the document the hub checked last and paints its cards, so the document''s diagnostics are shown beside an editor.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::follow_plain','function','Prints the side view''s rows to a pipe after each report, so the document''s diagnostics are shown without a terminal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::rendering','function','Lays the side view''s frame out as the visual language''s cells, so the terminal and a pipe paint one rendering that the rules check.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','follow::report_lines','function','Prints the lines `gandr view` prints for one report, so a face with no terminal shows the same text.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','run::Input','enum','Names what one read of the face''s input answered, so the input''s kind is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','run::InputSource','trait','Names where the face''s input comes from, so the input''s source is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','run::SMOKE_NOTE','constant','Names the line the smoke face prints, so the smoke face''s readiness is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','run::drive','function','Drives the face''s event loop, so the face''s frames are drawn and its keys are acted on.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','run::run','function','Drives the face over the terminal''s keys in raw mode on the alternate screen, so the face''s frames are drawn and its keys are acted on.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','run::run_smoke','function','Drives the face once on a headless backend and prints the smoke note, so the face''s readiness is checked without a terminal.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','theme::style_of','function','Names the style a span of a highlight role is painted in, so the role''s colour is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','theme::style_of_kind','function','Names the style a transcript line of a kind is painted in, so the kind''s colour is read.',NULL,'fits','sound',NULL);
INSERT INTO purpose VALUES('surface-tui','view::draw','function','Draws the face''s frame, so the transcript pane, the input pane and the status line are painted.',NULL,'fits','sound',NULL);
